begin;
do $qa$
declare owner_id uuid;sid uuid:=gen_random_uuid();pid uuid:=gen_random_uuid();pid2 uuid:=gen_random_uuid();claims jsonb;
issued jsonb;inv uuid;issued2 jsonb;inv2 uuid;r jsonb;oid uuid;ref text;hash text;batch jsonb;
begin
select user_id into strict owner_id from public.admin_memberships where access_level='owner' and active;
insert into auth.sessions(id,user_id,created_at) values(sid,owner_id,now());
claims:=jsonb_build_object('sub',owner_id,'iss','https://fsbqpyyprtymwrmzsacp.supabase.co/auth/v1','aal','aal2','session_id',sid,'amr',
jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now())::bigint),jsonb_build_object('method','totp','timestamp',extract(epoch from now())::bigint)));
perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',claims::text,true);
insert into public.partners(id,public_name,partner_type,slug,public_code,status) values(pid,'QA WhatsApp A','loja','qa-wa-'||pid,upper(left(replace(pid::text,'-',''),8)),'draft');
insert into public.partners(id,public_name,partner_type,slug,public_code,status) values(pid2,'QA WhatsApp B','loja','qa-wa-'||pid2,upper(left(replace(pid2::text,'-',''),8)),'draft');
issued:=public.admin_partner_portal(jsonb_build_object('action','issue','partner_id',pid,'email','qa@example.invalid','opt_in',true,'contact_confirmed',true));
inv:=(issued->>'id')::uuid;
issued2:=public.admin_partner_portal(jsonb_build_object('action','issue','partner_id',pid2,'email','qb@example.invalid','opt_in',true,'contact_confirmed',true));inv2:=(issued2->>'id')::uuid;
if has_function_privilege('anon','public.partner_whatsapp_ingest_test(jsonb)','EXECUTE') or has_function_privilege('authenticated','public.partner_whatsapp_ingest_test(jsonb)','EXECUTE') then raise exception 'QA ingest grants';end if;
if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='partner_whatsapp' and c.relkind='r' and not c.relrowsecurity) then raise exception 'QA RLS';end if;
if has_schema_privilege('authenticated','partner_whatsapp','USAGE') then raise exception 'QA schema grants';end if;
begin perform public.admin_partner_whatsapp_test('{"action":"mode","mode":"real"}');raise exception 'QA real mode accepted';exception when others then if sqlerrm<>'WHATSAPP_REAL_DISABLED' then raise;end if;end;
begin update partner_whatsapp.config set real_send=true;raise exception 'QA real send accepted';exception when check_violation then null;end;
perform public.admin_partner_whatsapp_test(jsonb_build_object('action','bind','invite_id',inv,'label','QA-CONTACT-A','consent_version','qa-contact-v1'));
begin perform public.admin_partner_whatsapp_test(jsonb_build_object('action','bind','invite_id',inv2,'label','QA-CONTACT-A','consent_version','qa-contact-v1'));raise exception 'QA cross bind';exception when others then if sqlerrm<>'WHATSAPP_CONTACT_DENIED' then raise;end if;end;
perform public.admin_partner_whatsapp_test(jsonb_build_object('action','bind','invite_id',inv2,'label','QA-CONTACT-B','consent_version','qa-contact-v1'));
perform public.admin_partner_portal(jsonb_build_object('action','prepare_message','id',inv));
perform public.admin_partner_whatsapp_test(jsonb_build_object('action','sync_queue','invite_id',inv));
perform public.admin_partner_whatsapp_test(jsonb_build_object('action','sync_queue','invite_id',inv));
if (select count(*) from partner_whatsapp.outbox where invite_id=inv)<>1 then raise exception 'QA duplicate queue';end if;
select id into oid from partner_whatsapp.outbox where invite_id=inv;
begin perform public.admin_partner_whatsapp_test(jsonb_build_object('action','simulate','invite_id',inv,'id',oid,'confirmed',true));raise exception 'QA disabled simulate';exception when others then if sqlerrm<>'WHATSAPP_SIMULATION_DENIED' then raise;end if;end;
perform public.admin_partner_whatsapp_test('{"action":"mode","mode":"test_synthetic"}');
r:=public.admin_partner_whatsapp_test(jsonb_build_object('action','simulate','invite_id',inv,'id',oid,'confirmed',true));ref:=r->>'delivery_ref';hash:=partner_portal.hash(ref);
begin perform public.admin_partner_whatsapp_test(jsonb_build_object('action','simulate','invite_id',inv,'id',oid,'confirmed',true));raise exception 'QA simulate replay';exception when others then if sqlerrm<>'WHATSAPP_REPLAY_DENIED' then raise;end if;end;
batch:=jsonb_build_array(jsonb_build_object('event_hash',repeat('a',64),'kind','status','delivery_hash',hash,'state','delivered'));
r:=public.partner_whatsapp_ingest_test(batch);
if r->>'accepted'<>'1' or r->>'ai_calls'<>'0' then raise exception 'QA status processing';end if;
r:=public.partner_whatsapp_ingest_test(batch);if r->>'duplicates'<>'1' then raise exception 'QA dedupe';end if;
perform public.partner_whatsapp_ingest_test(jsonb_build_array(jsonb_build_object('event_hash',repeat('b',64),'kind','status','delivery_hash',hash,'state','sent')));
perform public.partner_whatsapp_ingest_test(jsonb_build_array(jsonb_build_object('event_hash',repeat('c',64),'kind','status','delivery_hash',hash,'state','failed')));
if (select state from partner_whatsapp.outbox where id=oid)<>'delivered' then raise exception 'QA status regression';end if;
begin perform public.partner_whatsapp_ingest_test(jsonb_build_array(jsonb_build_object('event_hash',repeat('a',64),'kind','drop')));raise exception 'QA collision';exception when others then if sqlerrm<>'WHATSAPP_EVENT_COLLISION' then raise;end if;end;
-- Late invalid event must roll back every earlier receipt/effect in the batch.
begin perform public.partner_whatsapp_ingest_test(jsonb_build_array(jsonb_build_object('event_hash',repeat('d',64),'kind','opt_out','contact_label','QA-CONTACT-A'),'{"kind":"invalid"}'::jsonb));raise exception 'QA invalid batch';exception when others then if sqlerrm<>'WHATSAPP_EVENTS_DENIED' then raise;end if;end;
if exists(select 1 from partner_whatsapp.receipts where event_hash=repeat('d',64)) or (select opted_out from partner_portal.invites where id=inv) then raise exception 'QA non atomic batch';end if;
insert into partner_portal.messages(invite_id,kind,state) values(inv,'d2','pending'),(inv,'d5','pending');
perform public.admin_partner_whatsapp_test(jsonb_build_object('action','sync_queue','invite_id',inv));
batch:=jsonb_build_array(jsonb_build_object('event_hash',repeat('e',64),'kind','opt_out','contact_label','QA-CONTACT-A'));
perform public.partner_whatsapp_ingest_test(batch);perform public.partner_whatsapp_ingest_test(batch);
if not (select suppressed from partner_whatsapp.contacts where label='QA-CONTACT-A') or not (select opted_out from partner_portal.invites where id=inv) then raise exception 'QA optout';end if;
if exists(select 1 from partner_whatsapp.outbox where invite_id=inv and state='queued') or exists(select 1 from partner_portal.messages where invite_id=inv and state='pending') then raise exception 'QA reminders';end if;
if (select opted_out from partner_portal.invites where id=inv2) then raise exception 'QA crossed optout';end if;
if (select count(*) from partner_whatsapp.audit where kind='opt_out' and invite_id=inv)<>1 then raise exception 'QA optout audit replay';end if;
issued:=public.admin_partner_portal(jsonb_build_object('action','issue','partner_id',pid,'email','qa@example.invalid','opt_in',true,'contact_confirmed',true));
begin perform public.admin_partner_whatsapp_test(jsonb_build_object('action','bind','invite_id',issued->>'id','label','QA-CONTACT-A','consent_version','qa-contact-v1'));raise exception 'QA suppression reset';exception when others then if sqlerrm<>'WHATSAPP_CONTACT_DENIED' then raise;end if;end;
perform public.admin_partner_whatsapp_test('{"action":"mode","mode":"disabled"}');
begin perform public.partner_whatsapp_ingest_test('[]');raise exception 'QA disabled ingest';exception when others then if sqlerrm<>'WHATSAPP_DISABLED' then raise;end if;end;
perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);
begin perform public.admin_partner_whatsapp_test('{"action":"list"}');raise exception 'QA AAL1';exception when insufficient_privilege then null;end;
end $qa$;
rollback;
select 'PASS_WHATSAPP_PERSISTENCE_ROLLBACK' result;
